const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const filters=document.querySelectorAll('[data-filter]'),projects=document.querySelectorAll('.project');
filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;projects.forEach(project=>{project.hidden=button.dataset.filter!=='all'&&project.dataset.category!==button.dataset.filter;if(!project.hidden)count++;});document.getElementById('filter-status').textContent=`Showing ${count} project${count===1?'':'s'}.`;}));
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){if(!reduceMotion.matches)entry.target.classList.add('reveal');observer.unobserve(entry.target);}}),{threshold:.12});document.querySelectorAll('.hero-copy,.vision,.section-top h2,.section-top p,.project-art,.project-heading,.project>p,.projects-end,.about h2,.about-intro,.about-grid>div>p,.research,.toolkit,.contact h2,.contact-row,.email').forEach(el=>observer.observe(el));}
const canvas=document.getElementById('cloud'),context=canvas.getContext('2d'),toggle=document.getElementById('motion-toggle');let paused=reduceMotion.matches,visible=true,frameId=0,phase=0,last=0;
function draw(){context.clearRect(0,0,canvas.width,canvas.height);const points=[];for(let z=0;z<34;z++)for(let x=0;x<56;x++){const px=(x-28)*12,pz=(z-17)*12;const ridge=Math.sin(x*.15+phase)*24+Math.cos(z*.21+phase*.4)*22;const py=ridge-40*Math.exp(-((x-28)**2+(z-17)**2)/120);const angle=.42+Math.sin(phase*.2)*.12;const xx=px*Math.cos(angle)-pz*Math.sin(angle);const zz=px*Math.sin(angle)+pz*Math.cos(angle);points.push({x:390+xx,y:160+py+zz*.35,size:1.2+(zz+400)/700});}context.fillStyle='#ff99d3';for(const p of points){context.beginPath();context.arc(p.x,p.y,p.size,0,Math.PI*2);context.fill();}}
function loop(time){if(paused||!visible){frameId=0;return;}phase+=Math.min(time-last,40)*.00035;last=time;draw();frameId=requestAnimationFrame(loop);}
function sync(){toggle.textContent=paused?'Play motion':'Pause motion';toggle.setAttribute('aria-pressed',String(paused));if(!paused&&visible&&!frameId){last=performance.now();frameId=requestAnimationFrame(loop);}}
toggle.addEventListener('click',()=>{paused=!paused;sync();});reduceMotion.addEventListener('change',()=>{paused=reduceMotion.matches;sync();draw();});document.addEventListener('visibilitychange',()=>{visible=!document.hidden;sync();});if('IntersectionObserver'in window)new IntersectionObserver(([entry])=>{visible=entry.isIntersecting&&!document.hidden;sync();}).observe(canvas);draw();sync();
let scrollPending=false;window.addEventListener('scroll',()=>{if(scrollPending||reduceMotion.matches)return;scrollPending=true;requestAnimationFrame(()=>{const title=document.querySelector('.monument');title.style.transform=`scale(${1-Math.min(window.scrollY/900,1)*.035})`;scrollPending=false;});},{passive:true});
